"""光鸭云盘 HTTP 客户端。"""

from __future__ import annotations

import uuid
from typing import Any, Callable, Dict, Optional

import requests

from app.log import logger
from .oss_native_v357 import upload_file_multipart as _native_oss_multipart_upload


class GuangYaClient:
    """光鸭云盘 HTTP 客户端。"""

    ACCOUNT_BASE_URL = "https://account.guangyapan.com"
    API_BASE_URL = "https://api.guangyapan.com"
    DEFAULT_CLIENT_ID = "aMe-8VSlkrbQXpUR"

    @staticmethod
    def _mask_token(token: Optional[str], keep: int = 10) -> str:
        if not token:
            return ""
        token = str(token)
        if len(token) <= keep * 2:
            return token
        return f"{token[:keep]}...{token[-keep:]}"

    def __init__(
        self,
        access_token: str = None,
        refresh_token: str = None,
        client_id: str = None,
        device_id: str = None,
        on_token_refresh: Callable[[str, str], None] = None,
    ):
        self._access_token = (access_token or "").strip()
        self._refresh_token = (refresh_token or "").strip()
        self._client_id = (client_id or self.DEFAULT_CLIENT_ID).strip() or self.DEFAULT_CLIENT_ID
        self._device_id = self._normalize_device_id(device_id) or self._generate_device_id()
        self._on_token_refresh = on_token_refresh
        self._last_refresh_attempted = False
        self._last_refresh_invalid = False
        self._last_refresh_result: Dict[str, Any] = {}
        self._session = requests.Session()
        self._session.headers.update(self._build_common_headers())

    @property
    def device_id(self) -> str:
        return self._device_id

    @property
    def last_refresh_attempted(self) -> bool:
        return self._last_refresh_attempted

    @property
    def last_refresh_invalid(self) -> bool:
        return self._last_refresh_invalid

    @property
    def last_refresh_result(self) -> Dict[str, Any]:
        return self._last_refresh_result

    @staticmethod
    def _generate_device_id() -> str:
        return uuid.uuid4().hex

    @staticmethod
    def _normalize_device_id(device_id: Optional[str]) -> str:
        if not device_id:
            return ""
        return str(device_id).replace("-", "").strip()

    def _build_common_headers(self) -> Dict[str, str]:
        return {
            "Accept": "application/json, text/plain, */*",
            "Content-Type": "application/json",
            "Referer": "https://www.guangyupan.com/",
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/147.0.0.0 Safari/537.36"
            ),
            "Accept-Language": "zh-CN",
            "X-Client-Id": self._client_id,
            "X-Client-Version": "0.0.1",
            "X-Device-Id": self._device_id,
            "X-Device-Model": "chrome%2F147.0.0.0",
            "X-Device-Name": "PC-Chrome",
            "X-Device-Sign": f"wdi10.{self._device_id}xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
            "X-Net-Work-Type": "NONE",
            "X-Os-Version": "Win32",
            "X-Platform-Version": "1",
            "X-Protocol-Version": "301",
            "X-Provider-Name": "NONE",
            "X-Sdk-Version": "9.0.2",
        }

    @staticmethod
    def _is_auth_invalid_result(result: Dict[str, Any]) -> bool:
        if not isinstance(result, dict):
            return False
        combined = " ".join([
            str(result.get("error") or ""),
            str(result.get("msg") or ""),
            str(result.get("error_description") or ""),
            str(result),
        ]).lower()
        keywords = (
            "unauthenticated", "无效token", "authorize failed", "认证失败",
            "invalid_grant", "invalid token", "invalid_token", "token expiry",
        )
        return any(keyword.lower() in combined for keyword in keywords)

    def _get_auth_headers(self, use_access_token: bool = True) -> Dict[str, str]:
        headers = {
            "Authorization": f"Bearer {self._access_token}",
            "Did": self._device_id,
            "Dt": "4",
            "did": self._device_id,
            "dt": "4",
        }
        if use_access_token and self._access_token:
            headers["accessToken"] = self._access_token
        return headers

    def _request(
        self,
        method: str,
        url: str,
        data: dict = None,
        headers: dict = None,
        need_auth: bool = True,
        retry_on_401: bool = True,
        treat_http_error_as_response: bool = False,
        timeout: int = 30,
    ) -> Dict[str, Any]:
        req_headers = self._session.headers.copy()
        if headers:
            req_headers.update(headers)
        if need_auth and self._access_token:
            req_headers.update(self._get_auth_headers())

        if need_auth:
            logger.debug(
                "【光鸭云盘助手】发起请求: %s %s, device_id=%s, access_token=%s, refresh_token=%s",
                method.upper(), url, self._device_id,
                self._mask_token(self._access_token), self._mask_token(self._refresh_token),
            )

        try:
            method_upper = method.upper()
            if method_upper == "GET":
                response = self._session.get(url, headers=req_headers, params=data, timeout=timeout)
            elif method_upper == "PUT":
                response = self._session.put(url, headers=req_headers, data=data, timeout=timeout)
            else:
                response = self._session.post(url, headers=req_headers, json=data, timeout=timeout)
            response.raise_for_status()
            if not response.text:
                return {"msg": "success", "code": 0}
            return response.json()
        except requests.exceptions.HTTPError as err:
            status_code = err.response.status_code if err.response is not None else None
            if treat_http_error_as_response and err.response is not None:
                try:
                    return err.response.json()
                except Exception:
                    return {
                        "msg": "error",
                        "code": status_code or -1,
                        "error": err.response.text[:500] if err.response.text else str(err),
                    }
            if status_code == 401 and retry_on_401 and need_auth:
                logger.info(
                    "【光鸭云盘助手】Token 失效，尝试刷新: access_token=%s, refresh_token=%s, device_id=%s",
                    self._mask_token(self._access_token), self._mask_token(self._refresh_token), self._device_id,
                )
                if self.refresh_access_token():
                    return self._request(
                        method=method,
                        url=url,
                        data=data,
                        headers=headers,
                        need_auth=need_auth,
                        retry_on_401=False,
                        treat_http_error_as_response=treat_http_error_as_response,
                        timeout=timeout,
                    )
            detail = f"{status_code} {err.response.reason}" if err.response is not None else str(err)
            try:
                if err.response is not None and err.response.text:
                    detail = f"{detail} - {err.response.text[:500]}"
            except Exception:
                pass
            logger.error("【光鸭云盘助手】请求失败: %s - %s", url, detail)
            return {"msg": "error", "code": -1, "error": detail}
        except requests.exceptions.RequestException as err:
            logger.error("【光鸭云盘助手】请求失败: %s - %s", url, err)
            return {"msg": "error", "code": -1, "error": str(err)}

    def get_device_code(self) -> Optional[Dict[str, Any]]:
        result = self._request(
            method="POST",
            url=f"{self.ACCOUNT_BASE_URL}/v1/auth/device/code",
            data={"scope": "user", "client_id": self._client_id},
            need_auth=False,
        )
        if result.get("error"):
            return None
        return result

    def poll_device_code(self, device_code: str) -> Optional[Dict[str, Any]]:
        result = self._request(
            method="POST",
            url=f"{self.ACCOUNT_BASE_URL}/v1/auth/token",
            data={
                "grant_type": "urn:ietf:params:oauth:grant-type:device_code",
                "device_code": device_code,
                "client_id": self._client_id,
            },
            need_auth=False,
            treat_http_error_as_response=True,
        )
        if result.get("error") == "authorization_pending":
            return {"waiting": True, "message": "等待扫码中..."}
        if result.get("access_token"):
            self._access_token = result.get("access_token") or ""
            self._refresh_token = result.get("refresh_token") or ""
            return result
        return None

    def refresh_access_token(self) -> bool:
        self._last_refresh_attempted = True
        self._last_refresh_invalid = False
        self._last_refresh_result = {}
        if not self._refresh_token:
            self._last_refresh_invalid = True
            self._last_refresh_result = {"error": "missing_refresh_token", "msg": "refresh_token 为空"}
            logger.warning("【光鸭云盘助手】刷新失败：refresh_token 为空")
            return False
        old_access_token = self._access_token
        old_refresh_token = self._refresh_token
        result = self._request(
            method="POST",
            url=f"{self.ACCOUNT_BASE_URL}/v1/auth/token",
            data={
                "grant_type": "refresh_token",
                "refresh_token": self._refresh_token,
                "client_id": self._client_id,
            },
            need_auth=False,
        )
        self._last_refresh_result = result if isinstance(result, dict) else {"result": result}
        if result.get("access_token"):
            self._access_token = result.get("access_token") or ""
            self._refresh_token = result.get("refresh_token") or self._refresh_token
            self._last_refresh_invalid = False
            logger.info(
                "【光鸭云盘助手】Token 刷新成功: access_token %s -> %s, refresh_token %s -> %s",
                self._mask_token(old_access_token), self._mask_token(self._access_token),
                self._mask_token(old_refresh_token), self._mask_token(self._refresh_token),
            )
            if self._on_token_refresh:
                try:
                    self._on_token_refresh(self._access_token, self._refresh_token)
                except Exception as err:
                    logger.error("【光鸭云盘助手】Token 刷新回调失败: %s", err)
            return True
        self._last_refresh_invalid = self._is_auth_invalid_result(result)
        logger.warning(
            "【光鸭云盘助手】Token 刷新失败: device_id=%s, refresh_token=%s, auth_invalid=%s, response=%s",
            self._device_id, self._mask_token(old_refresh_token), self._last_refresh_invalid, result,
        )
        return False

    def get_user_info(self) -> Dict[str, Any]:
        return self._request("GET", f"{self.ACCOUNT_BASE_URL}/v1/user/me")

    def get_assets(self) -> Dict[str, Any]:
        return self._request("POST", f"{self.API_BASE_URL}/nd.bizassets.s/v1/get_assets", data={})

    def get_file_list(
        self,
        parent_id: str = "",
        page_size: int = 100,
        order_by: int = 3,
        sort_type: int = 1,
        file_types: list = None,
        page: int = 0,
        dir_type: int = None,
    ) -> Dict[str, Any]:
        data = {
            "parentId": parent_id or "",
            "page": page,
            "pageSize": page_size,
            "orderBy": order_by,
            "sortType": sort_type,
            "fileTypes": file_types or [],
        }
        if dir_type is not None:
            data["dirType"] = dir_type
        return self._request(
            method="POST",
            url=f"{self.API_BASE_URL}/nd.bizuserres.s/v1/file/get_file_list",
            data=data,
        )

    def create_dir(self, parent_id: str, dir_name: str, fail_if_exist: bool = True) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/file/create_dir",
            data={"parentId": parent_id or "", "dirName": dir_name, "failIfNameExist": fail_if_exist},
        )

    def rename(self, file_id: str, new_name: str) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/file/rename",
            data={"fileId": file_id, "newName": new_name},
        )

    def delete_file(self, file_ids: list) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/file/delete_file",
            data={"fileIds": file_ids},
        )

    def move_file(self, file_ids: list, target_parent_id: str) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/file/move_file",
            data={"fileIds": file_ids, "parentId": target_parent_id},
        )

    def copy_file(self, file_ids: list, target_parent_id: str) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/file/copy_file",
            data={"fileIds": file_ids, "parentId": target_parent_id},
        )

    def get_download_url(self, file_id: str) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/get_res_download_url",
            data={"fileId": file_id},
        )

    def get_upload_token(
        self,
        file_name: str,
        file_size: int,
        file_md5: str,
        parent_id: str = "",
        capacity: int = 1,
    ) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/get_res_center_token",
            data={
                "capacity": capacity,
                "name": file_name,
                "res": {"fileSize": file_size, "md5": file_md5},
                "parentId": parent_id or "",
            },
        )

    def check_flash_upload(
        self,
        task_id: str,
        gcid: str,
        file_size: int = None,
        file_name: str = None,
        parent_id: str = None,
    ) -> Dict[str, Any]:
        data = {"taskId": task_id, "gcid": gcid}
        if file_size is not None:
            data["fileSize"] = file_size
        if file_name:
            data["name"] = file_name
        if parent_id is not None:
            data["parentId"] = parent_id
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/check_can_flash_upload", data=data,
        )

    def get_resume_token(self, task_id: str, file_size: int) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/get_res_center_resume_token",
            data={"capacity": 2, "res": {"fileSize": file_size}, "taskId": task_id},
        )

    def get_file_info_by_task_id(self, task_id: str) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/file/get_info_by_task_id",
            data={"taskId": task_id},
        )

    def get_task_status(self, task_id: str) -> Dict[str, Any]:
        return self._request(
            "POST", f"{self.API_BASE_URL}/nd.bizuserres.s/v1/get_task_status",
            data={"taskId": task_id},
        )

    def upload_file_multipart(
        self,
        endpoint: str,
        bucket_name: str,
        object_path: str,
        file_path: str,
        oss_access_key_id: str,
        oss_access_key_secret: str,
        security_token: str,
        progress_callback: Callable = None,
    ) -> Optional[str]:
        """使用 MoviePilot 已有 requests 直接执行 OSS STS 分片上传。"""
        try:
            return _native_oss_multipart_upload(
                endpoint=endpoint,
                bucket_name=bucket_name,
                object_path=object_path,
                file_path=file_path,
                oss_access_key_id=oss_access_key_id,
                oss_access_key_secret=oss_access_key_secret,
                security_token=security_token,
                progress_callback=progress_callback,
            )
        except Exception as err:
            logger.error("【光鸭云盘助手】OSS 原生分片上传失败: %s", err)
            return None

sources.guangya_network_resilience_v347.py:
"""v3.4.7：光鸭上游 DNS/连接异常的降噪、退避与自动整理保护。

目标：
1. DNS/连接瞬断不再由 legacy 客户端每次都打 ERROR；统一在兼容层重试并节流告警。
2. 同一主机连续失败后进入短暂熔断，避免目录扫描、账号页刷新和整理链一起放大故障。
3. 用户信息/空间信息短缓存，网络抖动时复用最近成功值，不清空登录态。
4. 自动整理在文件 API 熔断期间安全延后；扫描中途断网时标记 truncated，禁止用不完整
   inventory 清理已有状态。

不改变光鸭 API 业务语义，也不绕过 MoviePilot 的识别、分类、整理规则。
"""

from __future__ import annotations

import copy
import threading
import time
from typing import Any, Callable, Dict, Optional
from urllib.parse import urlparse

import requests

from app.log import logger

from .guangya_client import GuangYaClient
from .organizer_folder_stream import GuangYaFolderStreamMixin


_TRANSIENT_HTTP_STATUS = {408, 425, 429, 500, 502, 503, 504}
_RETRY_DELAYS = (1.0, 2.0)
_CONTROL_CACHE_TTL = 60.0
_MAX_CIRCUIT_SECONDS = 30.0
_WARN_INTERVAL = 30.0


def _host(url: str) -> str:
    return str(urlparse(str(url or "")).hostname or url or "unknown")


def _ensure_runtime(client: GuangYaClient) -> None:
    if getattr(client, "_guangya_network_v347_ready", False):
        return
    client._guangya_network_v347_ready = True
    client._guangya_network_lock = threading.RLock()
    client._guangya_network_hosts = {}
    client._guangya_control_cache = {}


def _state_for(client: GuangYaClient, host: str) -> Dict[str, Any]:
    _ensure_runtime(client)
    with client._guangya_network_lock:
        state = client._guangya_network_hosts.get(host)
        if state is None:
            state = {
                "failures": 0,
                "circuit_until": 0.0,
                "last_warn_at": 0.0,
                "last_error": "",
                "outage": False,
                "last_success_at": 0.0,
            }
            client._guangya_network_hosts[host] = state
        return state


def _transient_result(result: Any) -> bool:
    if not isinstance(result, dict):
        return False
    if result.get("transient_network"):
        return True
    text = str(result.get("error") or result.get("msg") or "")
    markers = (
        "NameResolutionError",
        "Temporary failure in name resolution",
        "Failed to resolve",
        "ConnectionError",
        "Connection aborted",
        "Connection reset",
        "Read timed out",
        "ConnectTimeout",
        "ReadTimeout",
        "Max retries exceeded",
        "network_circuit_open",
    )
    return any(marker.casefold() in text.casefold() for marker in markers)


def _mark_success(client: GuangYaClient, host: str) -> None:
    state = _state_for(client, host)
    recovered = False
    with client._guangya_network_lock:
        recovered = bool(state.get("outage"))
        state["failures"] = 0
        state["circuit_until"] = 0.0
        state["last_error"] = ""
        state["outage"] = False
        state["last_success_at"] = time.time()
    if recovered:
        logger.info("【光鸭云盘助手】【网络】%s 已恢复，继续处理挂起任务", host)


def _mark_failure(client: GuangYaClient, host: str, error: str) -> float:
    state = _state_for(client, host)
    now_mono = time.monotonic()
    should_warn = False
    with client._guangya_network_lock:
        state["failures"] = int(state.get("failures") or 0) + 1
        failures = int(state["failures"])
        cooldown = min(5.0 * (2 ** max(failures - 1, 0)), _MAX_CIRCUIT_SECONDS)
        state["circuit_until"] = now_mono + cooldown
        state["last_error"] = str(error or "")
        state["outage"] = True
        last_warn_at = float(state.get("last_warn_at") or 0.0)
        if not last_warn_at or now_mono - last_warn_at >= _WARN_INTERVAL:
            state["last_warn_at"] = now_mono
            should_warn = True
    if should_warn:
        logger.warning(
            "【光鸭云盘助手】【网络】%s DNS/连接暂不可用，已完成本轮重试；"
            "暂停该主机请求 %.0fs，期间保留登录态和自动整理状态",
            host,
            cooldown,
        )
    return cooldown


def _circuit_result(client: GuangYaClient, url: str) -> Optional[Dict[str, Any]]:
    host = _host(url)
    state = _state_for(client, host)
    now_mono = time.monotonic()
    with client._guangya_network_lock:
        until = float(state.get("circuit_until") or 0.0)
        if until <= now_mono:
            return None
        retry_after = max(until - now_mono, 0.0)
        return {
            "msg": "error",
            "code": -1,
            "error": "network_circuit_open",
            "transient_network": True,
            "network_host": host,
            "retry_after": retry_after,
            "detail": str(state.get("last_error") or ""),
        }


def _request_once(
    client: GuangYaClient,
    *,
    method: str,
    url: str,
    data: Optional[dict],
    headers: Optional[dict],
    need_auth: bool,
    retry_on_401: bool,
    treat_http_error_as_response: bool,
    timeout: int,
) -> Dict[str, Any]:
    req_headers = client._session.headers.copy()
    if headers:
        req_headers.update(headers)
    if need_auth and client._access_token:
        req_headers.update(client._get_auth_headers())

    if need_auth:
        logger.debug(
            "【光鸭云盘助手】发起请求: %s %s, device_id=%s, access_token=%s, refresh_token=%s",
            method.upper(),
            url,
            client._device_id,
            client._mask_token(client._access_token),
            client._mask_token(client._refresh_token),
        )

    try:
        method_upper = method.upper()
        if method_upper == "GET":
            response = client._session.get(url, headers=req_headers, params=data, timeout=timeout)
        elif method_upper == "PUT":
            response = client._session.put(url, headers=req_headers, data=data, timeout=timeout)
        else:
            response = client._session.post(url, headers=req_headers, json=data, timeout=timeout)

        response.raise_for_status()
        if not response.text:
            return {"msg": "success", "code": 0}
        return response.json()

    except requests.exceptions.HTTPError as err:
        status_code = err.response.status_code if err.response is not None else None

        if status_code in _TRANSIENT_HTTP_STATUS:
            detail = f"{status_code} {err.response.reason}" if err.response is not None else str(err)
            try:
                if err.response is not None and err.response.text:
                    detail = f"{detail} - {err.response.text[:500]}"
            except Exception:
                pass
            return {
                "msg": "error",
                "code": status_code or -1,
                "error": detail,
                "transient_network": True,
                "network_kind": "http",
            }

        if treat_http_error_as_response and err.response is not None:
            try:
                return err.response.json()
            except Exception:
                return {
                    "msg": "error",
                    "code": status_code or -1,
                    "error": err.response.text[:500] if err.response.text else str(err),
                }

        if status_code == 401 and retry_on_401 and need_auth:
            logger.info(
                "【光鸭云盘助手】Token 失效，尝试刷新: access_token=%s, refresh_token=%s, device_id=%s",
                client._mask_token(client._access_token),
                client._mask_token(client._refresh_token),
                client._device_id,
            )
            if client.refresh_access_token():
                return client._request(
                    method=method,
                    url=url,
                    data=data,
                    headers=headers,
                    need_auth=need_auth,
                    retry_on_401=False,
                    treat_http_error_as_response=treat_http_error_as_response,
                    timeout=timeout,
                )

        detail = f"{status_code} {err.response.reason}" if err.response is not None else str(err)
        try:
            if err.response is not None and err.response.text:
                detail = f"{detail} - {err.response.text[:500]}"
        except Exception:
            pass

        logger.error("【光鸭云盘助手】请求失败: %s - %s", url, detail)
        return {"msg": "error", "code": -1, "error": detail}

    except (
        requests.exceptions.ConnectionError,
        requests.exceptions.Timeout,
        requests.exceptions.ProxyError,
    ) as err:
        # 由外层统一重试和节流告警，避免 legacy 每个请求都打一条 ERROR。
        return {
            "msg": "error",
            "code": -1,
            "error": str(err),
            "transient_network": True,
            "network_kind": type(err).__name__,
        }

    except requests.exceptions.RequestException as err:
        # 参数、证书等非典型请求错误不做熔断，保留 ERROR 便于诊断。
        logger.error("【光鸭云盘助手】请求失败: %s - %s", url, err)
        return {"msg": "error", "code": -1, "error": str(err)}


def _request(
    client: GuangYaClient,
    method: str,
    url: str,
    data: dict = None,
    headers: dict = None,
    need_auth: bool = True,
    retry_on_401: bool = True,
    treat_http_error_as_response: bool = False,
    timeout: int = 30,
) -> Dict[str, Any]:
    _ensure_runtime(client)

    if circuit := _circuit_result(client, url):
        return circuit

    host = _host(url)
    last_result: Dict[str, Any] = {}
    max_attempts = len(_RETRY_DELAYS) + 1

    for attempt in range(1, max_attempts + 1):
        last_result = _request_once(
            client,
            method=method,
            url=url,
            data=data,
            headers=headers,
            need_auth=need_auth,
            retry_on_401=retry_on_401,
            treat_http_error_as_response=treat_http_error_as_response,
            timeout=timeout,
        )
        if not _transient_result(last_result):
            _mark_success(client, host)
            return last_result

        if attempt < max_attempts:
            delay = _RETRY_DELAYS[attempt - 1]
            logger.debug(
                "【光鸭云盘助手】【网络】%s 第 %s/%s 次失败，%.0fs 后重试: %s",
                host,
                attempt,
                max_attempts,
                delay,
                last_result.get("error") or last_result.get("msg"),
            )
            time.sleep(delay)

    cooldown = _mark_failure(
        client,
        host,
        str(last_result.get("error") or last_result.get("msg") or last_result),
    )
    result = dict(last_result or {})
    result["transient_network"] = True
    result["network_host"] = host
    result["retry_after"] = cooldown
    return result


def _cache_success(result: Any) -> bool:
    if not isinstance(result, dict) or _transient_result(result):
        return False
    if result.get("error"):
        return False
    code = result.get("code")
    return code in (None, 0) or result.get("msg") == "success" or isinstance(result.get("data"), dict)


def _cached_control_call(
    client: GuangYaClient,
    key: str,
    call: Callable[[], Dict[str, Any]],
) -> Dict[str, Any]:
    _ensure_runtime(client)
    now = time.monotonic()

    with client._guangya_network_lock:
        cached = client._guangya_control_cache.get(key)
        if cached and now - float(cached.get("at") or 0.0) < _CONTROL_CACHE_TTL:
            return copy.deepcopy(cached["value"])

    result = call() or {}
    if _cache_success(result):
        with client._guangya_network_lock:
            client._guangya_control_cache[key] = {
                "at": time.monotonic(),
                "value": copy.deepcopy(result),
            }
        return result

    if _transient_result(result):
        with client._guangya_network_lock:
            cached = client._guangya_control_cache.get(key)
            if cached:
                stale = copy.deepcopy(cached["value"])
                stale["_guangya_stale_cache"] = True
                stale["_guangya_network_unavailable"] = True
                return stale

    return result


def _network_status(client: GuangYaClient, host: Optional[str] = None) -> Dict[str, Any]:
    _ensure_runtime(client)
    now_mono = time.monotonic()
    with client._guangya_network_lock:
        if host:
            states = {host: dict(client._guangya_network_hosts.get(host) or {})}
        else:
            states = {
                name: dict(value)
                for name, value in client._guangya_network_hosts.items()
            }

    hosts: Dict[str, Any] = {}
    available = True
    for name, state in states.items():
        until = float(state.get("circuit_until") or 0.0)
        retry_after = max(until - now_mono, 0.0)
        blocked = retry_after > 0
        if blocked:
            available = False
        hosts[name] = {
            "available": not blocked,
            "degraded": bool(state.get("outage")),
            "failures": int(state.get("failures") or 0),
            "retry_after": retry_after,
            "last_error": str(state.get("last_error") or ""),
            "last_success_at": float(state.get("last_success_at") or 0.0),
        }
    return {"available": available, "hosts": hosts}


def _api_network_status(plugin: Any) -> Dict[str, Any]:
    api = getattr(plugin, "_guangya_api", None)
    client = getattr(api, "client", None) or getattr(plugin, "_client", None)
    if not client:
        return {"available": True, "hosts": {}}
    getter = getattr(client, "get_network_status", None)
    if not callable(getter):
        return {"available": True, "hosts": {}}
    host = _host(getattr(client, "API_BASE_URL", "https://api.guangyapan.com"))
    try:
        return dict(getter(host) or {})
    except Exception:
        return {"available": True, "hosts": {}}


def _network_retry_after(status: Dict[str, Any]) -> float:
    values = [
        float(item.get("retry_after") or 0.0)
        for item in (status.get("hosts") or {}).values()
        if isinstance(item, dict)
    ]
    return max(values or [0.0])


def install_network_resilience_v347() -> None:
    if getattr(GuangYaClient, "_guangya_network_resilience_v347", False):
        return

    original_user_info = GuangYaClient.get_user_info
    original_assets = GuangYaClient.get_assets
    original_iter_groups = GuangYaFolderStreamMixin._iter_folder_groups
    original_scan = GuangYaFolderStreamMixin.run_organize_monitor_scan

    def get_user_info(client: GuangYaClient) -> Dict[str, Any]:
        return _cached_control_call(client, "user_info", lambda: original_user_info(client))

    def get_assets(client: GuangYaClient) -> Dict[str, Any]:
        return _cached_control_call(client, "assets", lambda: original_assets(client))

    def iter_groups(plugin: Any, root_path: str, scan_meta: Dict[str, Any]):
        before = _api_network_status(plugin)
        if not before.get("available", True):
            scan_meta["truncated"] = True
            scan_meta["network_deferred"] = True
            scan_meta["network_retry_after"] = _network_retry_after(before)
            return

        try:
            for group in original_iter_groups(plugin, root_path, scan_meta):
                current = _api_network_status(plugin)
                if not current.get("available", True):
                    # 当前 group 可能只扫描了一部分，绝不能把它交给后续状态机。
                    scan_meta["truncated"] = True
                    scan_meta["network_deferred"] = True
                    scan_meta["network_retry_after"] = _network_retry_after(current)
                    return
                yield group
        except Exception:
            current = _api_network_status(plugin)
            if not current.get("available", True):
                # 例如 get_item/list 因 DNS 失败返回空后触发“目录不存在”；网络已明确异常时
                # 将其视为安全延后，而不是目录真的被删除。
                scan_meta["truncated"] = True
                scan_meta["network_deferred"] = True
                scan_meta["network_retry_after"] = _network_retry_after(current)
                return
            raise

        after = _api_network_status(plugin)
        if not after.get("available", True):
            scan_meta["truncated"] = True
            scan_meta["network_deferred"] = True
            scan_meta["network_retry_after"] = _network_retry_after(after)

    def run_scan(plugin: Any, manual: bool = False) -> Dict[str, Any]:
        before = _api_network_status(plugin)
        if not before.get("available", True):
            retry_after = max(int(_network_retry_after(before)), 1)
            status = plugin._save_monitor_status(
                scan_in_progress=False,
                network_deferred=True,
                network_retry_after=retry_after,
                network_message="光鸭文件 API DNS/连接暂不可用，自动整理已安全延后",
            )
            return {
                "success": True,
                "message": f"光鸭网络/DNS暂不可用，本轮扫描已安全延后，约 {retry_after}s 后自动重试",
                "data": status,
            }

        result = original_scan(plugin, manual=manual)
        after = _api_network_status(plugin)
        if not after.get("available", True):
            retry_after = max(int(_network_retry_after(after)), 1)
            status = plugin._save_monitor_status(
                network_deferred=True,
                network_retry_after=retry_after,
                network_message="扫描期间光鸭文件 API 网络中断；本轮 inventory 已按截断处理，不清理旧状态",
            )
            if isinstance(result, dict):
                result["success"] = True
                result["message"] = (
                    f"扫描期间检测到光鸭网络/DNS中断，本轮已安全停止并保留已有状态，"
                    f"约 {retry_after}s 后自动重试"
                )
                result["data"] = status
            return result

        plugin._save_monitor_status(
            network_deferred=False,
            network_retry_after=0,
            network_message="",
        )
        return result

    GuangYaClient._request = _request
    GuangYaClient.get_user_info = get_user_info
    GuangYaClient.get_assets = get_assets
    GuangYaClient.get_network_status = _network_status

    GuangYaFolderStreamMixin._iter_folder_groups = iter_groups
    GuangYaFolderStreamMixin.run_organize_monitor_scan = run_scan

    GuangYaClient._guangya_network_resilience_v347 = True


__all__ = ["install_network_resilience_v347"]

sources.guangya_path_resolution_v369.py:
"""v3.6.9：光鸭路径解析分页、实例缓存隔离与严格目录读取。

长期运行中自动整理高度依赖 ``get_item(path) -> list(dir)``。旧实现存在三个会互相放大的问题：

1. ``_path_to_id`` 每一级只读取 get_file_list 第 0 页；父目录超过 page_size（默认 100）时，
   第二页以后的真实目录会被误判为“不存在”。
2. ``_id_cache`` / ``_item_cache`` 定义为类属性，热重载、新账号或新 API 实例会继承旧实例的
   path->fileId 缓存，可能把已经变化的目录继续解析到旧 fileId。
3. legacy ``list`` 遇到上游 API 失败时直接 break 并返回当前结果，调用方无法区分“真实空目录”
   与“网络/API 失败后的空列表”。自动整理因此可能把故障误判为资源已经搬空。

本模块不改变 MoviePilot 业务规则，只收紧光鸭存储查询语义：
- 路径逐级完整分页；
- 每个 GuangYaApi 实例拥有独立缓存；
- ``list_strict`` 只有上游明确成功时才返回列表，失败必须抛异常；
- ``get_item`` 复用逐级解析时已经建立的 item cache，避免再列一次父目录。
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, List, Optional

from app.sdk.logging import logger

from .guangya_api_v112 import GuangYaApi


_PATCH_FLAG = "_guangya_path_resolution_v369"


def _response_success(response: Any) -> bool:
    if not isinstance(response, dict):
        return False
    return response.get("code", -1) == 0 or response.get("msg") == "success"


def _response_error(response: Any) -> str:
    if not isinstance(response, dict):
        return repr(response)
    return str(
        response.get("error")
        or response.get("msg")
        or response.get("message")
        or f"code={response.get('code')}"
    )


def _page_has_more(data: Dict[str, Any], page_size: int, page_items: int, accumulated: int) -> bool:
    try:
        total = int(data.get("total") or 0)
    except (TypeError, ValueError):
        total = 0
    if page_items <= 0:
        return False
    if total > 0:
        return accumulated < total
    return page_items >= page_size


def install_path_resolution_v369() -> None:
    """幂等安装到当前 V3 GuangYaApi；不修改 V2。"""
    if getattr(GuangYaApi, _PATCH_FLAG, False):
        return

    previous_init = GuangYaApi.__init__
    previous_get_item = GuangYaApi.get_item

    def __init__(self: GuangYaApi, *args: Any, **kwargs: Any) -> None:
        previous_init(self, *args, **kwargs)
        # legacy 把缓存定义成类属性；必须在实例初始化时遮蔽，禁止热重载/多账号共享旧 fileId。
        self._id_cache = {}
        self._item_cache = {}

    def _path_to_id(self: GuangYaApi, path: str) -> str:
        normalized_path = self._normalize_path(path)
        if normalized_path == "/":
            return ""
        cached = str(self._id_cache.get(normalized_path) or "")
        if cached:
            return cached

        current_id = ""
        current_path = "/"
        for part in Path(normalized_path).parts[1:]:
            page = 0
            found: Optional[Dict[str, Any]] = None
            accumulated = 0
            while True:
                response = self.client.get_file_list(
                    parent_id=current_id,
                    page_size=self._page_size,
                    order_by=self._order_by,
                    sort_type=self._sort_type,
                    file_types=[],
                    page=page,
                )
                if not _response_success(response):
                    raise RuntimeError(
                        f"【光鸭云盘助手】解析路径 {normalized_path} 时读取目录失败: "
                        f"parent={current_path} page={page} error={_response_error(response)}"
                    )

                data = dict(response.get("data") or {})
                items = list(data.get("list") or [])
                accumulated += len(items)
                for item in items:
                    if str(item.get("fileName") or "") == part:
                        found = dict(item)
                        break
                if found is not None:
                    break
                if not _page_has_more(data, self._page_size, len(items), accumulated):
                    break
                page += 1

            if found is None:
                raise FileNotFoundError(f"【光鸭云盘助手】{normalized_path} 不存在")

            current_id = str(found.get("fileId") or "")
            current_path = (
                f"{current_path.rstrip('/')}/{part}" if current_path != "/" else f"/{part}"
            )
            self._cache_path_id(current_path, current_id)
            parent_path = str(Path(current_path).parent).replace("\\", "/") or "/"
            self._build_file_item_from_api(parent_path, found)

        return current_id

    def list_strict(self: GuangYaApi, fileitem: Any) -> List[Any]:
        """完整分页目录读取；上游失败抛异常，绝不伪装成成功空目录。"""
        if str(getattr(fileitem, "type", "") or "") == "file":
            item = self.detail(fileitem)
            return [item] if item else []

        normalized_dir_path = self._normalize_path(getattr(fileitem, "path", "/"))
        file_id = self._normalize_fileid(getattr(fileitem, "fileid", ""), normalized_dir_path)
        if normalized_dir_path != "/" and not file_id:
            file_id = self._path_to_id(normalized_dir_path)

        results: List[Any] = []
        page = 0
        while True:
            response = self.client.get_file_list(
                parent_id=file_id,
                page_size=self._page_size,
                order_by=self._order_by,
                sort_type=self._sort_type,
                file_types=[],
                page=page,
            )
            if not _response_success(response):
                raise RuntimeError(
                    f"【光鸭云盘助手】读取目录失败: path={normalized_dir_path} page={page} "
                    f"error={_response_error(response)}"
                )
            data = dict(response.get("data") or {})
            item_list = list(data.get("list") or [])
            for item in item_list:
                results.append(self._build_file_item_from_api(normalized_dir_path, item))
            if not _page_has_more(data, self._page_size, len(item_list), len(results)):
                break
            page += 1
        return results

    def get_item(self: GuangYaApi, path: Path):
        normalized = self._normalize_path(str(path))
        if normalized == "/":
            return previous_get_item(self, path)

        cached_item = self._restore_cached_item(normalized)
        if cached_item:
            return cached_item
        try:
            file_id = self._path_to_id(normalized)
        except FileNotFoundError:
            return None

        # 分页 _path_to_id 已把最终 segment 构造成 FileItem 并写入 cache，避免旧实现再次
        # 枚举父目录；只有异常兼容场景才退回旧父目录确认逻辑。
        resolved = self._restore_cached_item(normalized)
        if resolved and str(getattr(resolved, "fileid", "") or "") == str(file_id or ""):
            return resolved
        return previous_get_item(self, path)

    def refresh_item(self: GuangYaApi, path: Path):
        """丢弃指定路径陈旧缓存后重新从远端解析。"""
        normalized = self._normalize_path(str(path))
        self._invalidate_path_cache(normalized)
        return get_item(self, Path(normalized))

    GuangYaApi.__init__ = __init__
    GuangYaApi._path_to_id = _path_to_id
    GuangYaApi.list_strict = list_strict
    GuangYaApi.get_item = get_item
    GuangYaApi.refresh_item = refresh_item
    setattr(GuangYaApi, _PATCH_FLAG, True)
    logger.debug(
        "【光鸭云盘助手】【v3.6.9】路径查询增强已启用：完整分页、实例缓存隔离、严格目录失败语义"
    )


__all__ = ["install_path_resolution_v369"]
